	private readonly \Closure $clock;
	private readonly ?\Closure $authorizer;

	public function __construct(private readonly PanelWorkGraphStore $store,?callable $authorizer=null,?callable $clock=null,private readonly int $eventRetention=50000,private readonly int $receiptRetention=10000){$this->authorizer=$authorizer!==null?\Closure::fromCallable($authorizer):null;$this->clock=$clock!==null?\Closure::fromCallable($clock):static fn():string=>gmdate('c');if($eventRetention<100||$receiptRetention<100){throw new \InvalidArgumentException('Work graph retention must be at least 100.');}}
