		return$this->store->transaction($tenantId,function(array &$state)use($tenantId,$digest,$fingerprint,$ability,$actorId,$itemId,$mutation):PanelWorkReceipt{$existing=$state['receipts'][$digest]??null;if(is_array($existing)){if(!hash_equals((string)($existing['fingerprint']??''),$fingerprint)){throw new \LogicException('Work graph idempotency key was reused for another command.');}$eventPayload=$state['events'][(string)$existing['event_id']]??null;if(!is_array($eventPayload)){throw new \UnexpectedValueException('Work graph replay receipt references a missing event.');}$event=PanelWorkEvent::restore($eventPayload);$itemPayload=$state['items'][$event->itemId()]??null;return new PanelWorkReceipt($event,is_array($itemPayload)?PanelWorkItem::restore($itemPayload):null,true);}$now=$this->now();$correlation='corr_'.substr(hash('sha256',$tenantId.'|'.$digest),0,40);$causation='cause_'.substr(hash('sha256',$fingerprint),0,40);$result=$mutation($state,$now,$correlation);[$next,$before,$details,$reversible]=$result;$causationId=(string)($result[4]??$causation);$state['sequence']++;$previous=$state['events']!==[]?(string)$state['events'][array_key_last($state['events'])]['hash']:(string)$state['anchor_hash'];$event=PanelWorkEvent::make($state['sequence'],$tenantId,$next->id(),str_starts_with($ability,'work.')?substr($ability,5):$ability,$actorId,$now,$before?->jsonSerialize(),$next->jsonSerialize(),$details,$reversible,$correlation,$causationId,$previous);$state['items'][$next->id()]=$next->jsonSerialize();$state['events'][$event->id()]=$event->jsonSerialize();$state['receipts'][$digest]=['fingerprint'=>$fingerprint,'event_id'=>$event->id()];$state['receipt_order'][]=$digest;$this->prune($state);return new PanelWorkReceipt($event,$next);},$ability,['actor_hash'=>hash('sha256',$actorId),'item_hash'=>hash('sha256',$itemId)]);
	}

	/** @param array<string,mixed> $state */ private function required(array $state,string $id):PanelWorkItem {$payload=$state['items'][$id]??null;if(!is_array($payload)){throw new \OutOfBoundsException('Work item does not exist.');}return PanelWorkItem::restore($payload);}
	/** @param array<string,mixed> $context */ private function authorize(string $ability,array $context):void {if($this->authorizer===null){throw new \LogicException('Work graph authorization is not configured.');}try{$decision=($this->authorizer)($ability,$context,$this);$allowed=$decision===true||($decision instanceof PanelSecurityDecision&&$decision->allowed())||($decision instanceof PanelPolicyDecision&&$decision->allowed())||(is_array($decision)&&($decision['allowed']??false)===true);}catch(\Throwable $error){throw new \LogicException('Work graph authorization failed closed.',0,$error);}if(!$allowed){throw new \LogicException('Work graph operation is not authorized.');}}
	/** @param array<string,mixed> $state */ private function prune(array &$state):void {$eventExcess=count($state['events'])-$this->eventRetention;if($eventExcess>0){$ids=array_slice(array_keys($state['events']),0,$eventExcess);foreach($ids as$id){$state['anchor_hash']=(string)$state['events'][$id]['hash'];unset($state['events'][$id]);}}$receiptExcess=count($state['receipt_order'])-$this->receiptRetention;if($receiptExcess>0){$removed=array_splice($state['receipt_order'],0,$receiptExcess);foreach($removed as$digest){unset($state['receipts'][$digest]);}}}
	private function now():string {$value=($this->clock)();if(!$value instanceof \DateTimeInterface&&!is_string($value)&&!is_int($value)){throw new \UnexpectedValueException('Work graph clock must return an instant.');}return PanelOperationsGuard::instant($value);}
	private function idempotency(string $key):string {$key=trim($key);if($key===''||strlen($key)>256){throw new \InvalidArgumentException('Work graph idempotency key is invalid.');}return$key;}
	private function edgeKey(string $from,string $to,string $type):string{return hash('sha256',$from.'|'.$type.'|'.$to);}
}
